"""Educación Financiera EPJA Media N1 y N2, módulo 4 (parte 2): economía cotidiana, ingreso y consumo, transacciones, presupuesto y protección al consumidor. OAD-13 a OAD-16. Todo en papel; cifras inventadas y rotuladas como de ejemplo; sin tasas, comisiones, impuestos ni plazos legales reales."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = ("Papel, lápiz y goma. Las boletas, tablas, presupuestos y casos vienen escritos en cada ficha y sus cifras son de ejemplo, inventadas; "
             "no se usa dinero real, calculadora real ni internet. Nada de esto es consejo financiero personal: para una decisión real, pide información a la institución y lee tu contrato.")
build = make_build(MATERIALS)

O13, O14, O15, O16 = (f"EPJA-EFIN-NM1y2-OAD-{n}" for n in ("13", "14", "15", "16"))
PRIOR = ["Conozco el vuelto, las compras de la feria y las cuentas del hogar de mi vida diaria.", "Sé sumar, restar y multiplicar cantidades en pesos."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, prior=None):
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=op, reinforce=rf, extend=ex_)


